PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?riskTolerance ?timeHorizon
WHERE {
  ?investor rdf:type wm:Investor .

  # Identify the investor by ID or name (case‑insensitive)
  {
    ?investor wm:investorId ?investorId .
    FILTER(LCASE(STR(?investorId)) = "INV-002")
  } UNION {
    ?investor wm:investorName ?name .
    FILTER(LCASE(STR(?name)) = "INV-002")
    BIND(?name AS ?investorId)
  }

  # Risk tolerance (literal or via referenced node)
  OPTIONAL { ?investor wm:riskTolerance ?rtLit . }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtNode .
    OPTIONAL { ?rtNode rdfs:label ?rtLabel . }
  }
  BIND(COALESCE(?rtLit, ?rtLabel) AS ?riskTolerance)

  # Time horizon (literal or via referenced node)
  OPTIONAL { ?investor wm:timeHorizon ?thLit . }
  OPTIONAL {
    ?investor wm:hasTimeHorizon ?thNode .
    OPTIONAL { ?thNode rdfs:label ?thLabel . }
  }
  BIND(COALESCE(?thLit, ?thLabel) AS ?timeHorizon)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
