PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COALESCE(STR(?typeLabel), "NULL") AS ?cash_flow_type)
       (COUNT(?cashFlowId) AS ?transaction_count)
       (SUM(?amountSum) AS ?total_amount)
WHERE {
  {
    SELECT ?cashFlowId ?typeLabel (SUM(?amt) AS ?amountSum)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowId ?cashFlowId .
      OPTIONAL { ?cf wm:amount ?amount . }
      BIND( IF(BOUND(?amount), xsd:decimal(?amount), 0) AS ?amt )
      OPTIONAL {
        ?cf wm:hasCashFlowType ?type .
        OPTIONAL { ?type rdfs:label ?typeLabel . }
      }
    }
    GROUP BY ?cashFlowId ?typeLabel
  }
}
GROUP BY ?typeLabel

