PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(?holdCount) AS ?matching_holding_count)
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId ?sector (COUNT(?holding) AS ?holdCount)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:sector ?sector .
    }
    GROUP BY ?investorId ?sector
  }

  {
    SELECT DISTINCT ?investorId ?sector
    WHERE {
      ?alloc rdf:type wm:SectorAllocation ;
            wm:investorId ?investorId ;
            wm:sector ?sector .
    }
  }
}
GROUP BY ?investorId ?investorName

