  # Portfolio health with riskScore > 60
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScoreRaw .
  BIND(xsd:decimal(?riskScoreRaw) AS ?risk_score) .
  FILTER(?risk_score > 60)
}

